# Build final grid and submit
center = 8
height = 18
width = 17

output = [[0]*width for _ in range(height)]

# 2s at (r, center±r) for r=0 to 8
for r in range(9):
    c1, c2 = center - r, center + r
    if 0 <= c1 < width:
        output[r][c1] = 2
    if 0 <= c2 < width and c1 != c2:
        output[r][c2] = 2

# 1s from translated 14x13 pattern
ones_14x13_by_row = {
    3: [5], 4: [6], 5: [3,7], 6: [4,8],
    7: [0,4,8,12], 8: [1,5,9], 9: [2,6,10], 10: [3,7,11],
