    for c in (x + 2 for x in cols):
        if 0 <= c < 17:
            output[r][c] = 1

# Extrapolate rows 14-17
repeat = {14: 10, 15: 11, 16: 12, 17: 13}
for ext_r, base in repeat.items():
    for c in (x + 2 for x in ones_14x13_by_row[base]):
